use "./main.css"
use Card from "./card.qubc"

component Main {
  props { title: string }
  template {
    div(class="app") {
      h1(class="app__title") { {title} }
      Card(label="click me" /)
    }
  }
}

use "./card.css"

component Card {
  props { label: string }
  events { PICK({ label }) }
  template {
    button(class="card" @click:PICK) { {label} }
  }
}
